const tabId = 343605414;
const pageData = await browserjs(tabId, () => {
  // Let's search for any text with $ or price
  const allText = document.body.innerText;
  const priceMatches = allText.match(/(\$\d+|\bprice\b|\bpricing\b|\bfee\b|\brate\b)/gi);

  // Check window data / redux / react state
  const reactRoot = document.getElementById('react-root');
  let fiber = null;
  if (reactRoot) {
    const key = Object.keys(reactRoot).find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactInternalInstance$'));
    fiber = reactRoot[key];
  }

  // Let's find groomer profile data in fiber or window
  let groomerData = null;
  let curr = fiber;
  while (curr) {
    if (curr.memoizedProps?.groomer || curr.memoizedProps?.profile || curr.memoizedProps?.data) {
      groomerData = curr.memoizedProps.groomer || curr.memoizedProps.profile || curr.memoizedProps.data;
      break;
    }
    if (curr.memoizedState?.groomer || curr.memoizedState?.profile) {
      groomerData = curr.memoizedState.groomer || curr.memoizedState.profile;
      break;
    }
    curr = curr.child;
  }

  return {
    priceMatches,
    hasGroomerData: !!groomerData,
    groomerKeys: groomerData ? Object.keys(groomerData) : null,
    links: Array.from(document.querySelectorAll('a')).map(a => ({ text: a.innerText, href: a.href })).filter(a => a.href && !a.href.includes('facebook') && !a.href.includes('twitter') && !a.href.includes('instagram'))
  };
});
console.log(JSON.stringify(pageData, null, 2));

