const tabId = 343605414;
const groomersCheck = await browserjs(tabId, async () => {
  // Let's fetch the profiles of the 4 groomers returned in search
  const slugs = [
    'woofies-of-cherry-hill',
    'abbie-the-groomie',
    'a-muddy-paw-pet-salon',
    'emilys-groom-room'
  ];

  const results = [];
  for (const slug of slugs) {
    try {
      const res = await fetch(`/groomer/${slug}`);
      const html = await res.text();
      // Extract window.marketplace = ...
      const match = html.match(/window\.marketplace\s*=\s*(\{[\s\S]*?\});\s*<\/script>/);
      let state = null;
      if (match) {
        try {
          state = JSON.parse(match[1]);
        } catch (e) {
          // try evaluating or regex
        }
      }

      // Let's also check for dollar signs in html
      const dollarMatches = html.match(/\$\s*\d+(?:\.\d{2})?/g);

      const services = state?.state?.app?.organization?.service?.service_child?.services_offered?.map(s => ({
        title: s.title,
        price_min: s.pivot?.price_min,
        price_max: s.pivot?.price_max,
        price_range: s.pivot?.price_range,
        description: s.pivot?.description
      }));

      const packages = state?.state?.app?.organization?.service?.service_child?.available_packages;
      const specials = state?.state?.app?.organization?.service?.service_child?.available_specials;

      results.push({
        slug,
        orgName: state?.state?.app?.organization?.name,
        services,
        packages,
        specials,
        dollarMatches
      });
    } catch (err) {
      results.push({ slug, error: err.message });
    }
  }
  return results;
});
console.log(JSON.stringify(groomersCheck, null, 2));

