const abbieDetails = await browserjs(tabId, async () => {
  const res = await fetch('/groomer/abbie-the-groomie');
  const text = await res.text();
  // Find where prices might be
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, 'text/html');

  // Find script containing window.marketplace
  const script = Array.from(doc.querySelectorAll('script')).find(s => s.textContent.includes('window.marketplace'));
  let services = [];
  if (script) {
    const jsonText = script.textContent.replace(/^[\s\S]*?window\.marketplace\s*=\s*/, '').replace(/;\s*$/, '');
    try {
      const data = JSON.parse(jsonText);
      services = data.state.app.organization.service.service_child.services_offered.map(s => ({
        title: s.title,
        price_min: s.pivot?.price_min,
        price_max: s.pivot?.price_max,
        price_range: s.pivot?.price_range,
        description: s.pivot?.description
      }));
    } catch (e) {
      return { error: e.message, snippet: jsonText.slice(0, 500) };
    }
  }

  return {
    services
  };
});
