const tabId = 343605414;
const allResults = await browserjs(tabId, async () => {
  const slugs = [
    'woofies-of-cherry-hill',
    'abbie-the-groomie',
    'a-muddy-paw-pet-salon',
    'emilys-groom-room',
    'jens-grooming'
  ];

  const groomers = [];
  for (const slug of slugs) {
    try {
      const res = await fetch(`/groomer/${slug}`);
      if (!res.ok) continue;
      const text = await res.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, 'text/html');
      const script = Array.from(doc.querySelectorAll('script')).find(s => s.textContent.includes('window.marketplace'));
      if (!script) continue;
      const fn = new Function(script.textContent + '; return window.marketplace;');
      const data = fn();
      const org = data.state?.app?.organization;
      const services = org?.service?.service_child?.services_offered?.map(s => ({
        title: s.title,
        price_min: s.pivot?.price_min,
        price_max: s.pivot?.price_max,
        price_range: s.pivot?.price_range,
        description: s.pivot?.description
      }));
      groomers.push({
        name: org?.name,
        slug,
        address: `${org?.location?.address_1}, ${org?.location?.city || ''} ${org?.location?.zip || ''}`,
        services
      });
    } catch (e) {
      // ignore
    }
  }
  return groomers;
});

console.log(JSON.stringify(allResults, null, 2));

